<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import {ApiError,onIdentityChange} from '@/core/http'
import {can,currentProject,projectId,session} from '@/core/session'
import {otaCreateTransport,type OtaCreateTransport} from './ota-create-api'
import {otaMetadataDraft,prepareOtaMetadata,sameOtaMetadata,} from './ota-management-metadata-api'
import {validMainAppVersion,mainAppBinding,mainAppVersionProperties,sameExecutionBinding,type OtaVersionPropertyChoice} from './ota-main-app-api'
import MetadataFields from './OtaFirmwareMetadataFields.vue'
import TargetFields from './OtaFirmwareTargetFields.vue'
import {otaTargetDraft,prepareOtaTargetConditions,sameOtaTargetConditions,type OtaTargetedMainRequest,type OtaTargetedMainCreation} from './ota-target-conditions-api'
import type {OtaFirmware} from './ota-read-api'
import type {ModelVersion} from '../device-types/model-version-api'
import type {TaskChoice} from '../rules/task-choices'
const props=withDefaults(defineProps<{transport?:OtaCreateTransport}>(),{transport:()=>otaCreateTransport})
const emit=defineEmits<{close:[];saved:[id:string];locked:[value:boolean]}>()
const readable=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||'')&&can('ota:read'))
const allowed=computed(()=>readable.value&&currentProject.value?.status==='ACTIVE'&&can('ota:deploy')&&can('device:read'))
const choices=ref<TaskChoice[]>([]),cursor=ref<string>(),more=ref(false),loading=ref(false),typeId=ref(''),version=ref(''),versionProperty=ref(''),properties=ref<readonly OtaVersionPropertyChoice[]>([]),propertyLoading=ref(false),fields=ref(otaMetadataDraft()),targets=ref(otaTargetDraft()),model=ref<ModelVersion>(),busy=ref(false),unknown=ref(false),error=ref(''),created=ref<OtaFirmware>()
let generation=0,alive=true,read:AbortController|undefined,write:AbortController|undefined,choiceRead:AbortController|undefined,intent:Readonly<{project:string;body:OtaTargetedMainRequest;key:string}>|undefined
const frozen=computed(()=>busy.value||unknown.value),ready=computed(()=>{if(!allowed.value||frozen.value||!model.value||model.value.deviceTypeId!==typeId.value||!validMainAppVersion(version.value)||!properties.value.some(row=>row.key===versionProperty.value))return false;try{prepareOtaMetadata(fields.value);prepareOtaTargetConditions(targets.value);return true}catch{return false}})
watch(frozen,value=>emit('locked',value),{immediate:true,flush:'sync'})
function reset(){generation++;read?.abort();write?.abort();choiceRead?.abort();choices.value=[];cursor.value=undefined;more.value=false;loading.value=false;typeId.value='';version.value='';versionProperty.value='';properties.value=[];propertyLoading.value=false;fields.value=otaMetadataDraft();targets.value=otaTargetDraft();model.value=undefined;busy.value=false;unknown.value=false;created.value=undefined;intent=undefined;error.value='';if(allowed.value)void loadTypes()}
function current(g:number){return alive&&g===generation&&readable.value}
async function loadTypes(){if(!allowed.value||loading.value||frozen.value)return;const g=generation;choiceRead=new AbortController();loading.value=true;error.value='';try{const result=await props.transport.types(projectId.value,cursor.value,choiceRead.signal);if(!current(g))return;const all=new Map(choices.value.map(row=>[row.id,row]));for(const row of result.options)all.set(row.id,row);choices.value=[...all.values()];cursor.value=result.nextCursor||undefined;more.value=result.hasMore}catch(cause){if(current(g))error.value=cause instanceof Error?cause.message:'读取类型失败'}finally{if(current(g))loading.value=false}}
async function select(value:string){if(!allowed.value||frozen.value)return;read?.abort();choiceRead?.abort();loading.value=false;const g=++generation;typeId.value=value;targets.value=otaTargetDraft();model.value=undefined;versionProperty.value='';properties.value=[];propertyLoading.value=false;error.value='';if(!choices.value.some(row=>row.id===value))return;read=new AbortController();propertyLoading.value=true;try{const result=await props.transport.model(projectId.value,value,read.signal);if(!current(g)||typeId.value!==value)return;const snapshot=await props.transport.snapshot(projectId.value,value,result,read.signal);if(!current(g)||typeId.value!==value)return;properties.value=mainAppVersionProperties(snapshot);model.value=result}catch(cause){if(current(g))error.value=cause instanceof ApiError&&cause.code===30052?'该类型没有已发布物模型，请先发布后再创建固件。':cause instanceof Error?cause.message:'读取模型失败'}finally{if(current(g))propertyLoading.value=false}}
function selectProperty(value:string){if(!allowed.value||frozen.value||!properties.value.some(row=>row.key===value))return;versionProperty.value=value}
function fixedMatches(row:OtaFirmware){return !!intent&&row.projectId===intent.project&&row.deviceTypeId===intent.body.deviceTypeId&&row.thingModelVersionId===intent.body.thingModelVersionId&&row.firmwareVersion===intent.body.firmwareVersion&&row.schemaDigest===model.value?.schemaDigest&&row.schemaDigestAlgorithm===model.value?.digestAlgorithm}
function originalMatches(receipt:OtaTargetedMainCreation){return !!intent&&fixedMatches(receipt.firmware)&&(!created.value||created.value.id===receipt.firmware.id)&&sameOtaMetadata(receipt.creationMetadata,intent.body.metadata)&&sameExecutionBinding(receipt.executionBinding,intent.body.executionBinding)&&sameOtaTargetConditions(receipt.creationTargetConditions,intent.body.targetConditions)}
async function verify(g:number){if(!intent||!readable.value)return;const receipt=await props.transport.recoverTargeted(intent.project,intent.key,write!.signal);if(!current(g))return;if(!originalMatches(receipt))throw new Error('原创建结果与本次资料不一致，请保留原请求核对');created.value=receipt.firmware;unknown.value=false;busy.value=false;emit('saved',receipt.firmware.id)}
async function submit(){if(!ready.value||!model.value)return;const g=generation;intent=Object.freeze({project:projectId.value,body:Object.freeze({deviceTypeId:typeId.value,thingModelVersionId:model.value.id,firmwareVersion:version.value,metadata:prepareOtaMetadata(fields.value),executionBinding:mainAppBinding(versionProperty.value),targetConditions:prepareOtaTargetConditions(targets.value)}),key:crypto.randomUUID()});write=new AbortController();busy.value=true;unknown.value=true;error.value='';let accepted=false;try{const row=await props.transport.createTargeted(intent.project,intent.body,intent.key,write.signal);accepted=true;if(!current(g))return;created.value=row;if(!fixedMatches(row))throw new Error('创建结果与本次选择不一致');await verify(g)}catch(cause){if(!current(g))return;unknown.value=accepted||!(cause instanceof ApiError)||cause.outcomeUnknown||cause.code===10010||cause.code===10014;error.value=unknown.value?'创建结果尚未核实，请读取原创建结果；不会重复创建。':cause instanceof Error?cause.message:'创建失败'}finally{if(current(g))busy.value=false}}
async function reread(){if(!readable.value||busy.value||!unknown.value||!intent)return;const g=generation;write=new AbortController();busy.value=true;error.value='';try{await verify(g)}catch(cause){if(current(g))error.value=cause instanceof ApiError&&cause.status===404?'原创建结果尚未可读，请稍后继续核对。':cause instanceof Error?cause.message:'读取失败'}finally{if(current(g))busy.value=false}}
function close(){if(!busy.value&&!unknown.value)emit('close')}
let previous:readonly [string,string|undefined,OtaCreateTransport]|undefined
function changedScope(){const same=previous?.[0]===projectId.value&&previous?.[1]===session.user?.accountId&&previous?.[2]===props.transport;previous=[projectId.value,session.user?.accountId,props.transport];if(same&&intent&&frozen.value){if(!readable.value||!allowed.value){generation++;read?.abort();write?.abort();choiceRead?.abort();busy.value=false;loading.value=false;propertyLoading.value=false}return}reset()}
watch([()=>projectId.value,()=>session.user?.accountId,readable,allowed,()=>props.transport],changedScope,{immediate:true,flush:'sync'})
const dispose=onIdentityChange(reset)
onScopeDispose(()=>{alive=false;generation++;read?.abort();write?.abort();choiceRead?.abort();dispose();emit('locked',false)})
</script>
<template><section class="ota-create"><p v-if="!readable" role="alert">当前没有版本资料读取权限。<span v-if="unknown">创建结果仍待核对，恢复权限后可继续读取原结果。</span></p><template v-else><p>选择设备类型并填写版本资料，创建后即可上传固件文件。</p><el-form label-position="top"><MetadataFields v-model="fields" section="name" :disabled="frozen||!allowed"/><el-form-item label="所属设备类型" required><el-select :model-value="typeId" aria-label="OTA设备类型" :disabled="frozen||!allowed" :loading="loading" filterable @update:model-value="select"><el-option v-for="row in choices" :key="row.id" :value="row.id" :label="row.label"/></el-select><el-button v-if="more" link :disabled="frozen||loading||!allowed" @click="loadTypes">加载更多类型</el-button></el-form-item><el-form-item label="版本属性" required><el-select :model-value="versionProperty" aria-label="OTA版本属性" @update:model-value="selectProperty" :disabled="frozen||!allowed||!model" :loading="propertyLoading" :placeholder="typeId?'请选择版本属性':'请先选择设备类型'"><el-option v-for="row in properties" :key="row.key" :value="row.key" :label="row.label"/></el-select><p v-if="model&&!properties.length" class="help">当前已发布模型没有文本属性，请在<router-link :to="`/device-types/${typeId}`">设备类型</router-link>中添加并发布后重新选择。</p></el-form-item><el-form-item label="版本号" required><el-input v-model="version" aria-label="OTA固件版本" maxlength="31" :disabled="frozen||!allowed" placeholder="例如 1.0 或 1.0.1"/><p class="help">填写两段或三段数字版本，版本属性创建后不可修改。</p></el-form-item><el-form-item label="模块"><span>main（主应用）</span></el-form-item><TargetFields v-model="targets" :device-type-id="typeId" :disabled="frozen||!allowed" :loader="transport.devices"/><MetadataFields v-model="fields" section="details" :disabled="frozen||!allowed"/></el-form><p v-if="error" role="alert">{{error}}</p><p v-if="unknown">原创建请求：{{intent?.key}}</p><footer><el-button :disabled="busy||unknown" @click="close">取消</el-button><el-button v-if="unknown" :loading="busy" @click="reread">读取原创建结果</el-button><el-button v-else type="primary" :disabled="!ready" :loading="busy" @click="submit">创建固件草稿</el-button></footer></template></section></template>
<style scoped>.ota-create p{line-height:1.6;overflow-wrap:anywhere}.ota-create .el-select{width:100%}.ota-create footer{display:flex;justify-content:flex-end;gap:8px}.ota-create [role=alert]{color:var(--el-color-danger)}</style>
